add_filter( 'woocommerce_account_menu_items', 'perfectpixel_hide_rename_account_tabs', 55 );

function perfectpixel_hide_rename_account_tabs( $items ) {
	foreach ( array_filter( array_map( 'trim', explode( ',', '{{hidden_account_tabs}}' ) ) ) as $key ) {
		unset( $items[ $key ] );
	}
	foreach ( explode( '|', '{{renamed_account_tabs}}' ) as $pair ) {
		$parts = array_map( 'trim', explode( '=', $pair, 2 ) );
		if ( 2 === count( $parts ) && isset( $items[ $parts[0] ] ) && '' !== $parts[1] ) {
			$items[ $parts[0] ] = $parts[1];
		}
	}
	return $items;
}
